import base64
import hashlib
import os
import struct
import sys
import zlib

# Expected properties of the embedded image. These are checked on every
# run, so a corrupted or truncated payload can never be written silently.
EXPECTED_WIDTH = 1024
EXPECTED_HEIGHT = 1024
EXPECTED_SIZE = 73622
EXPECTED_SHA256 = "faad68087a65a30fb07c9de2c741d46ef5dd0dfe54f52d35e0d70a7fd5c73d5c"
MAX_BYTES = 1048576  # the competition's 1 MiB cap

_PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


class InvalidImageError(ValueError):
    """Raised when the embedded PNG fails any structural check."""


def _iter_chunks(data):
    """Yield (chunk_type, chunk_data) for each PNG chunk in *data*.

    Verifies every chunk's length field against the remaining bytes and
    its CRC32 against the stored value. Stops after IEND and reports any
    trailing bytes as an error, so the file is a whole image and nothing
    more.
    """
    if not data.startswith(_PNG_SIGNATURE):
        raise InvalidImageError("missing PNG signature")
    pos = len(_PNG_SIGNATURE)
    seen_iend = False
    while pos < len(data):
        if seen_iend:
            raise InvalidImageError("trailing data after IEND chunk")
        if pos + 8 > len(data):
            raise InvalidImageError("truncated chunk header at offset %d" % pos)
        length, ctype = struct.unpack(">I4s", data[pos:pos + 8])
        body_start = pos + 8
        body_end = body_start + length
        crc_end = body_end + 4
        if crc_end > len(data):
            raise InvalidImageError("truncated %s chunk" % ctype.decode("latin-1"))
        chunk_data = data[body_start:body_end]
        stored_crc, = struct.unpack(">I", data[body_end:crc_end])
        actual_crc = zlib.crc32(ctype)
        actual_crc = zlib.crc32(chunk_data, actual_crc) & 0xFFFFFFFF
        if stored_crc != actual_crc:
            raise InvalidImageError(
                "CRC mismatch in %s chunk" % ctype.decode("latin-1"))
        yield ctype, chunk_data
        if ctype == b"IEND":
            seen_iend = True
        pos = crc_end
    if not seen_iend:
        raise InvalidImageError("missing IEND chunk")


def _validate_png(data):
    """Validate the decoded PNG and return its (width, height, colour type).

    Checks: size cap, signature, IHDR dimensions (exactly 1024x1024),
    8-bit depth, palette (3) or truecolour (2) colour type, compression
    method 0, filter method 0, interlace 0 or 1, CRC of every chunk,
    presence of at least one IDAT chunk, IHDR as the first chunk, a PLTE
    chunk whenever the colour type is palette (3), and no data after IEND.
    """
    if len(data) > MAX_BYTES:
        raise InvalidImageError(
            "image is %d bytes, over the 1 MiB cap" % len(data))
    if len(data) < len(_PNG_SIGNATURE) + 25:
        raise InvalidImageError("image too short to hold an IHDR chunk")
    width = height = None
    colour_type = None
    saw_idat = False
    saw_ihdr = False
    saw_plte = False
    first_chunk = True
    for ctype, chunk_data in _iter_chunks(data):
        if first_chunk and ctype != b"IHDR":
            raise InvalidImageError("first chunk is not IHDR")
        first_chunk = False
        if ctype == b"IHDR":
            if saw_ihdr:
                raise InvalidImageError("duplicate IHDR chunk")
            saw_ihdr = True
            if len(chunk_data) != 13:
                raise InvalidImageError("IHDR chunk is not 13 bytes")
            (width, height, bit_depth, colour_type, comp, filt,
             interlace) = struct.unpack(">IIBBBBB", chunk_data)
            if (width, height) != (EXPECTED_WIDTH, EXPECTED_HEIGHT):
                raise InvalidImageError(
                    "IHDR is %dx%d, expected %dx%d"
                    % (width, height, EXPECTED_WIDTH, EXPECTED_HEIGHT))
            if bit_depth != 8:
                raise InvalidImageError("bit depth is %d, expected 8"
                                        % bit_depth)
            if colour_type not in (2, 3):
                raise InvalidImageError("colour type %d is not 2 or 3"
                                        % colour_type)
            if comp != 0 or filt != 0:
                raise InvalidImageError("unsupported compression/filter method")
            if interlace not in (0, 1):
                raise InvalidImageError("bad interlace method %d" % interlace)
        elif ctype == b"PLTE":
            saw_plte = True
        elif ctype == b"IDAT":
            saw_idat = True
    if not saw_ihdr:
        raise InvalidImageError("missing IHDR chunk")
    if colour_type == 3 and not saw_plte:
        raise InvalidImageError(
            "palette image (colour type 3) without a PLTE chunk")
    if not saw_idat:
        raise InvalidImageError("missing IDAT chunk")
    return width, height, colour_type


def _decode_payload():
    """Decode, hash-check and validate the embedded PNG; return its bytes."""
    try:
        data = base64.b64decode(_B64, validate=True)
    except Exception as exc:
        raise InvalidImageError("base64 payload is not valid: %s" % exc)
    if len(data) != EXPECTED_SIZE:
        raise InvalidImageError(
            "decoded size %d does not match expected %d"
            % (len(data), EXPECTED_SIZE))
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED_SHA256:
        raise InvalidImageError(
            "sha256 mismatch: got %s, expected %s" % (digest, EXPECTED_SHA256))
    _validate_png(data)
    return data


def _resolve_output(argv):
    """Pick the output destination: argv path, env dir, or stdout (None).

    An explicit path argument wins. Otherwise MAKEFUN_OUTPUT_DIR, when set
    to a non-empty value, names the directory that receives entry.png.
    Otherwise the image goes to stdout as binary.
    """
    if len(argv) > 1 and argv[1].strip():
        return argv[1]
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "")
    if out_dir:
        return os.path.join(out_dir, "entry.png")
    return None


def main(argv=None):
    """Decode and validate the image, then write it to the destination."""
    if argv is None:
        argv = sys.argv
    try:
        data = _decode_payload()
    except InvalidImageError as exc:
        print("main.py: invalid image: %s" % exc, file=sys.stderr)
        return 1
    dest = _resolve_output(argv)
    if dest is None:
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
    else:
        parent = os.path.dirname(os.path.abspath(dest))
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(dest, "wb") as fh:
            fh.write(data)
    return 0


